<script>
 import ReportChart from '../../Components/ReportChart.svelte';
 export let customerData=[];
 let search='';let sort='spent';
 const money=n=>'Rp '+new Intl.NumberFormat('id-ID',{maximumFractionDigits:0}).format(Number(n)||0);
 $: filtered=customerData.filter(row=>[row.name,row.phone,row.email].some(v=>String(v||'').toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):Number(b[sort==='services'?'service_count':'total_spent'])-Number(a[sort==='services'?'service_count':'total_spent']));
 $: total=filtered.reduce((sum,row)=>sum+Number(row.total_spent||0),0);
 $: chart=[...filtered].sort((a,b)=>Number(b.total_spent)-Number(a.total_spent)).slice(0,5).map(row=>({label:row.name,value:Number(row.total_spent)||0}));
</script>
<svelte:head><title>Laporan Pelanggan - SST Bengkel</title></svelte:head>
<div class="report-workspace"><header class="management-heading"><div><div class="eyebrow">ANALISIS BENGKEL</div><h1>Laporan pelanggan</h1><p>Riwayat kunjungan dan pembayaran pelanggan bengkel.</p></div><a href="/reports" class="sst-button secondary">← Ringkasan laporan</a></header><nav class="report-tabs" aria-label="Jenis laporan"><a href="/reports">Ringkasan</a><a href="/reports/revenue">Pendapatan</a><a href="/reports/services">Servis</a><a class="active" href="/reports/customers" aria-current="page">Pelanggan</a></nav>
<div class="metric-grid three"><section class="metric-card"><span>Pelanggan</span><strong>{filtered.length}</strong><small>Sesuai pencarian</small></section><section class="metric-card"><span>Total pembayaran</span><strong>{money(total)}</strong><small>Hanya invoice lunas · seluruh periode</small></section><section class="metric-card"><span>Kunjungan servis</span><strong>{filtered.reduce((n,row)=>n+Number(row.service_count||0),0)}</strong><small>Jumlah SPK pelanggan</small></section></div>
<ReportChart title="5 pelanggan dengan pembayaran tertinggi" subtitle="Hanya pembayaran dari invoice lunas · seluruh periode" data={chart} money horizontal />
<section class="report-panel"><div class="panel-heading"><div><h2>Daftar pelanggan</h2><p>{filtered.length} pelanggan ditemukan</p></div><div class="report-search"><label class="sr-only" for="search">Cari pelanggan</label><input id="search" type="search" bind:value={search} placeholder="Cari nama atau nomor telepon" /><label class="sr-only" for="sort">Urutkan pelanggan</label><select id="sort" bind:value={sort}><option value="spent">Pembayaran tertinggi</option><option value="services">Kunjungan terbanyak</option><option value="name">Nama A–Z</option></select></div></div><div class="management-table-scroll"><table class="management-table"><thead><tr><th>Pelanggan</th><th>Kendaraan</th><th>Kunjungan</th><th>Servis terakhir</th><th class="money">Total pembayaran</th></tr></thead><tbody>{#each filtered as row}<tr><td><a class="text-link" href={`/customers/${row.id}`}>{row.name}</a><div class="secondary-text">{row.phone||'-'}</div></td><td>{row.vehicle_count||0} kendaraan</td><td>{row.service_count||0} SPK</td><td>{row.last_service_date?new Date(row.last_service_date).toLocaleDateString('id-ID'):'Belum servis'}</td><td class="money primary-text">{money(row.total_spent)}</td></tr>{:else}<tr><td colspan="5" class="empty-cell">Belum ada pelanggan yang sesuai dengan pencarian.</td></tr>{/each}</tbody></table></div></section></div>
